from h import *

S = []
G = 'Services and Security'

# ------------------------------------------------------------------ Device access, AAA, SFTP/SCP
qs = [
 Q('Which four steps are needed before a Cisco router accepts SSH logins with a local username?', ['Set a hostname and ip domain-name', 'Generate RSA keys (crypto key generate rsa)', 'Create a local user (username ... secret ...)', 'Configure the VTY lines with login local and transport input ssh'],
   ['Enable service password-encryption', 'Set an enable password with type 7', 'Configure ip http server'],
   'The RSA key name comes from the hostname and domain name, so those come first. Use a 2048-bit key and "ip ssh version 2".', card='List the steps to enable SSH with local login.'),
 Q('Why use "username admin secret ..." instead of "username admin password ..."?', 'secret stores a strong one-way hash; password stores clear text or weak type 7 encryption',
   ['secret is required for Telnet', 'password works only on the console', 'There is no difference'],
   'Type 7 (from service password-encryption) can be reversed instantly. secret uses type 5, 8 or 9 hashes.'),
 Q('Which statement correctly compares TACACS+ and RADIUS?', 'TACACS+ uses TCP 49 and encrypts the whole body; RADIUS uses UDP 1812/1813 and encrypts only the password',
   ['TACACS+ uses UDP; RADIUS uses TCP', 'Both encrypt the whole packet', 'RADIUS is Cisco proprietary'],
   'TACACS+ also separates authentication, authorization and accounting, allowing per-command authorization. That makes it the usual choice for device administration; RADIUS is the usual choice for network access (802.1X, VPN, Wi-Fi).'),
 Q('Which protocol is better suited to authorizing individual CLI commands for network administrators?', 'TACACS+', ['RADIUS', 'LDAP', 'SNMP'],
   'TACACS+ handles authorization as a separate step, so the server can approve each command.'),
 Q('With "aaa authentication login default group TACACS local", when is the local user database used?', 'Only when no TACACS+ server responds', ['When the TACACS+ server rejects the password', 'Always, before TACACS+', 'Never'],
   'The next method is tried only if the previous one gives no answer. A "reject" from the server is final. The local fallback stops you being locked out if the servers are down.',
   card='In a method list "group TACACS local", when is local used?'),
 Q('Which command must come first to use AAA method lists on IOS?', 'aaa new-model', ['aaa enable', 'aaa authentication enable', 'tacacs-server enable'],
   'aaa new-model turns on AAA. After that, login behaviour is controlled by method lists instead of the old line passwords.'),
 Q('Which RADIUS server configuration is correct on IOS XE?', 'radius server ISE1, then address ipv4 10.0.0.20 auth-port 1812 acct-port 1813, then key MySecret',
   ['radius-server ISE1 10.0.0.20 tcp 49', 'tacacs server ISE1 address 10.0.0.20 port 1812', 'aaa radius 10.0.0.20 key MySecret'],
   'Define the server, group it with "aaa group server radius NAME" if needed, and reference the group in the method list. The shared key must match the server.'),
 Q('Why should SCP or SFTP be used instead of TFTP or FTP to copy IOS images and configs?', 'They run over SSH, so files and credentials are encrypted and authenticated',
   ['They are faster because they use UDP', 'TFTP cannot copy configuration files', 'FTP needs a licence'],
   'TFTP has no authentication or encryption at all; FTP sends passwords in clear text.'),
 Q('Which command makes a router act as an SCP server so you can push files to it?', 'ip scp server enable', ['ip ftp server enable', 'service scp', 'ip ssh scp'],
   'SSH and AAA must also be set up (SCP uses the SSH login and needs exec authorization).'),
 Q('Which command copies an image from an SFTP server to flash?', 'copy sftp://admin@10.0.0.50/cat9k.bin flash:', ['copy tftp: sftp:', 'copy flash: sftp:', 'archive sftp flash:'],
   'Source first, destination second. "verify /md5 flash:cat9k.bin" then checks the file against the published hash.'),
 Q('After copying a new IOS image to flash, how do you check the file isn\'t corrupt?', 'Compare its hash with Cisco\'s published value using "verify /md5" (or /sha512)', ['Check that the file size is over 100 MB', 'Run show version', 'Ping the server again'],
   'A matching hash proves the file arrived intact and wasn\'t tampered with.'),
 Q('Which command limits SSH access to the VTY lines to the management subnet in standard ACL 10?', 'access-class 10 in (under line vty 0 15)', ['ip access-group 10 in (under line vty)', 'ip ssh access 10', 'login local 10'],
   'On lines it\'s access-class. On interfaces it\'s ip access-group.'),
 Q('What does "exec-timeout 5 0" do on a line?', 'Logs out an idle session after 5 minutes', ['Allows 5 login attempts', 'Locks the line for 5 minutes after a failure', 'Limits sessions to 5'],
   'Idle sessions left open are a risk. 0 0 means never time out, which you should avoid.'),
]
L = lesson(14,
 'Before anything else, devices need secure management access. This lesson covers local users and SSH, AAA with TACACS+ and RADIUS, and copying images and configurations securely with SCP and SFTP.',
 [
  ('Local users and SSH', [
    UL('hostname R1', 'ip domain-name example.com', 'crypto key generate rsa modulus 2048', 'ip ssh version 2', 'username admin privilege 15 secret Str0ngP@ss', 'line vty 0 15',
       ' login local', ' transport input ssh', ' exec-timeout 5 0', ' access-class 10 in'),
    UL('secret is hashed (type 5/8/9). password is clear text or weak type 7.', 'Telnet (TCP 23) sends passwords in the clear. Allow only SSH.', 'access-class filters who can reach the VTY lines.'),
    CK(0, 1, 11, 12)]),
  ('AAA', [
    P('AAA moves logins to a central server: Authentication (who are you), Authorization (what may you do), Accounting (what did you do).'),
    TB(['', 'TACACS+', 'RADIUS'], ['Transport', 'TCP 49', 'UDP 1812/1813 (or 1645/1646)'], ['Encrypts', 'Whole packet body', 'Password only'], ['AAA functions', 'Separate', 'Authn + authz combined'],
       ['Typical use', 'Device administration, per-command authorization', 'Network access: 802.1X, VPN, Wi-Fi'], ['Standard', 'Cisco-developed, published RFC 8907', 'Open standard']),
    UL('aaa new-model', 'tacacs server TAC1', ' address ipv4 10.0.0.10', ' key MyKey', 'aaa authentication login default group tacacs+ local', 'aaa authorization exec default group tacacs+ local'),
    TIP('"local" at the end is used only when the servers don\'t answer, not when they say no. It\'s your emergency way in.'),
    CK(2, 3, 4, 5, 6)]),
  ('Moving files securely', [
    P('IOS images and config backups move between devices and servers. TFTP has no security at all and FTP sends passwords in clear text. v2.0 wants SFTP and SCP, which both run over SSH.'),
    UL('Router as SCP server: ip scp server enable (with SSH and AAA authorization working).', 'Pull from a server: copy scp://admin@10.0.0.50/image.bin flash:   or   copy sftp://... flash:',
       'Back up config: copy running-config sftp://admin@10.0.0.50/r1.cfg', 'Check the image: verify /md5 flash:image.bin', 'Boot from it: boot system flash:image.bin, then save and reload.'),
    CK(7, 8, 9, 10)]),
 ],
 [('4.1', 'Configure network devices with local usernames and as AAA clients (TACACS+ and RADIUS) for management'), ('4.2', 'Manage device configuration and software files using secure file transfer (SFTP/SCP)')])
